41. /** Configurable Firebase options. */
42. public final class FirebaseOptions {
43. 
44.   private static final List<String> FIREBASE_SCOPES =
45.       ImmutableList.of(
46.           // Enables access to Firebase Realtime Database.
47.           "https://www.googleapis.com/auth/firebase.database",
48. 
49.           // Enables access to the email address associated with a project.
50.           "https://www.googleapis.com/auth/userinfo.email",
51. 
