62.   static final Supplier<GoogleCredentials> APPLICATION_DEFAULT_CREDENTIALS =
63.       new Supplier<GoogleCredentials>() {
64.         @Override
65.         public GoogleCredentials get() {
66.           try {
67.             return GoogleCredentials.getApplicationDefault().createScoped(FIREBASE_SCOPES);
68.           } catch (IOException e) {
