87.   private FirebaseOptions(@NonNull final FirebaseOptions.Builder builder) {
88.     this.databaseUrl = builder.databaseUrl;
89.     this.credentialsSupplier = checkNotNull(
90.         builder.credentialsSupplier, "FirebaseOptions must be initialized with setCredentials().");
91.     this.databaseAuthVariableOverride = builder.databaseAuthVariableOverride;
92.     this.projectId = builder.projectId;
93.     if (!Strings.isNullOrEmpty(builder.storageBucket)) {
94.       checkArgument(!builder.storageBucket.startsWith("gs://"),
95.           "StorageBucket must not include 'gs://' prefix.");
96.     }
97.     if (!Strings.isNullOrEmpty(builder.serviceAccountId)) {
98.       this.serviceAccountId = builder.serviceAccountId;
99.     } else {
100.       this.serviceAccountId = null;
101.     }
102.     this.storageBucket = builder.storageBucket;
103.     this.httpTransport = checkNotNull(builder.httpTransport,
104.         "FirebaseOptions must be initialized with a non-null HttpTransport.");
105.     this.jsonFactory = checkNotNull(builder.jsonFactory,
106.         "FirebaseOptions must be initialized with a non-null JsonFactory.");
107.     this.threadManager = checkNotNull(builder.threadManager,
108.         "FirebaseOptions must be initialized with a non-null ThreadManager.");
109.     checkArgument(builder.connectTimeout >= 0);
110.     this.connectTimeout = builder.connectTimeout;
111.     checkArgument(builder.readTimeout >= 0);
112.     this.readTimeout = builder.readTimeout;
113.     this.firestoreOptions = builder.firestoreOptions;
114.   }
