149.     private InstanceIdServiceErrorResponse safeParse(String response) {
150.       InstanceIdServiceErrorResponse parsed = new InstanceIdServiceErrorResponse();
151.       if (!Strings.isNullOrEmpty(response)) {
152.         // Parse the error response from the IID service.
153.         // Sample response: {"error": "error message text"}
154.         try {
155.           jsonFactory.createJsonParser(response).parse(parsed);
156.         } catch (IOException ignore) {
157.           // Ignore any error that may occur while parsing the error response. The server
