41.   private static final Map<Integer, ErrorCode> HTTP_ERROR_CODES =
42.       ImmutableMap.<Integer, ErrorCode>builder()
43.           .put(HttpStatusCodes.STATUS_CODE_BAD_REQUEST, ErrorCode.INVALID_ARGUMENT)
44.           .put(HttpStatusCodes.STATUS_CODE_UNAUTHORIZED, ErrorCode.UNAUTHENTICATED)
45.           .put(HttpStatusCodes.STATUS_CODE_FORBIDDEN, ErrorCode.PERMISSION_DENIED)
