47.           .put(HttpStatusCodes.STATUS_CODE_CONFLICT, ErrorCode.CONFLICT)
48.           .put(429, ErrorCode.RESOURCE_EXHAUSTED)
49.           .put(HttpStatusCodes.STATUS_CODE_SERVER_ERROR, ErrorCode.INTERNAL)
